import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";var i=JSON.parse(`{"title":"Mail Accounts","description":"","frontmatter":{},"headers":[],"relativePath":"documentation/local-server/mail-accounts.md","filePath":"documentation/local-server/mail-accounts.md","lastUpdated":1788551488000}`),a={name:`documentation/local-server/mail-accounts.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="mail-accounts" tabindex="-1">Mail Accounts <a class="header-anchor" href="#mail-accounts" aria-label="Permalink to “Mail Accounts”">​</a></h1><p>Configure and manage the email accounts used for automated mail operations through the Local Server.</p><hr><h2 id="adding-account" tabindex="-1">Adding an Account <a class="header-anchor" href="#adding-account" aria-label="Permalink to “Adding an Account”">​</a></h2><p>To add a new email account, click the <strong>+ Add Account</strong> button in the Local Server dashboard. You will need to provide the following details:</p><table tabindex="0"><thead><tr><th>Field</th><th>Description</th><th>Example</th></tr></thead><tbody><tr><td><strong>Account Name</strong></td><td>A friendly name to identify the account</td><td><code>Primary Gmail</code>, <code>Support Desk</code></td></tr><tr><td><strong>IMAP Host</strong></td><td>The IMAP server address</td><td><code>imap.gmail.com</code></td></tr><tr><td><strong>IMAP Port</strong></td><td>The port for secure IMAP connections</td><td><code>993</code></td></tr><tr><td><strong>SMTP Host</strong></td><td>The SMTP server address</td><td><code>smtp.gmail.com</code></td></tr><tr><td><strong>SMTP Port</strong></td><td>The port for secure SMTP connections</td><td><code>587</code> or <code>465</code></td></tr><tr><td><strong>Email Address</strong></td><td>The full email address of the account</td><td><code>user@gmail.com</code></td></tr><tr><td><strong>App Password</strong></td><td>Application-specific password (required for 2FA providers)</td><td>Generated App Password</td></tr></tbody></table><h3 id="common-email-provider-settings" tabindex="-1">Common Email Provider Settings <a class="header-anchor" href="#common-email-provider-settings" aria-label="Permalink to “Common Email Provider Settings”">​</a></h3><p>Use these configurations for standard email services:</p><table tabindex="0"><thead><tr><th>Provider</th><th>IMAP Host</th><th>IMAP Port</th><th>SMTP Host</th><th>SMTP Port</th></tr></thead><tbody><tr><td><strong>Gmail</strong></td><td><code>imap.gmail.com</code></td><td><code>993</code></td><td><code>smtp.gmail.com</code></td><td><code>587</code> / <code>465</code></td></tr><tr><td><strong>Yahoo</strong></td><td><code>imap.mail.yahoo.com</code></td><td><code>993</code></td><td><code>smtp.mail.yahoo.com</code></td><td><code>465</code> / <code>587</code></td></tr><tr><td><strong>Outlook / Office 365</strong></td><td><code>outlook.office365.com</code></td><td><code>993</code></td><td><code>smtp.office365.com</code></td><td><code>587</code></td></tr><tr><td><strong>iCloud</strong></td><td><code>imap.mail.me.com</code></td><td><code>993</code></td><td><code>smtp.mail.me.com</code></td><td><code>587</code></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">IMAP Requirement</p><p>Ensure that <strong>IMAP Access</strong> is enabled in your email provider&#39;s account security settings before attempting to connect. For accounts with Two-Factor Authentication (2FA) enabled (such as Gmail), generate an <strong>App Password</strong> instead of using your primary login password.</p></div><hr><h2 id="account-management" tabindex="-1">Account Management <a class="header-anchor" href="#account-management" aria-label="Permalink to “Account Management”">​</a></h2><p>Once an account is created, it will appear as an active card in the <strong>Mail Accounts</strong> list:</p><table tabindex="0"><thead><tr><th>Action</th><th>Purpose</th></tr></thead><tbody><tr><td><strong>Test IMAP</strong></td><td>Verifies inbox connection by attempting to authenticate with the IMAP server.</td></tr><tr><td><strong>Test SMTP</strong></td><td>Verifies mail transmission by attempting a handshake with the SMTP server.</td></tr><tr><td><strong>Edit Account</strong></td><td>Opens the account modal to modify host, port, or credential settings.</td></tr><tr><td><strong>Delete Account</strong></td><td>Removes the email account from the Local Server.</td></tr><tr><td><strong>View Emails</strong></td><td>Opens the built-in email viewer for this specific inbox.</td></tr></tbody></table><hr><h2 id="other-actions" tabindex="-1">Other Actions <a class="header-anchor" href="#other-actions" aria-label="Permalink to “Other Actions”">​</a></h2><ul><li><strong>Compose</strong>: Opens a composer window to manually draft and send an email through the selected account.</li></ul>`,17)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};